style='body{margin:0;background:#111315;color:#e3e6e7;font:15px/1.65 system-ui,sans-serif}main{max-width:1460px;padding:42px clamp(18px,4vw,64px);margin:auto}h1{font-weight:550;letter-spacing:-.04em;font-size:clamp(28px,4vw,44px);margin:0 0 10px}p{color:#a7b0b5;max-width:85ch}nav{display:flex;gap:12px;flex-wrap:wrap;margin:24px 0 34px}a{color:#bad2c5;text-decoration:none}nav a{padding:9px 14px;border:1px solid #343b40;border-radius:7px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,470px),1fr));gap:24px}figure{margin:0;border:1px solid #2c3338;border-radius:10px;overflow:hidden;background:#181c1f}img{display:block;width:100%;height:350px;object-fit:contain;object-position:top;background:#090a0b}figcaption{padding:14px 18px;color:#d3dcda;font-size:13px}a:focus-visible{outline:2px solid #bad2c5;outline-offset:3px}'
